		t.Fatalf("invoice %s %v", r.Body, err)
	}
	if r := do(t, srv, "GET", "/api/invoices/"+v.ID, "key-globex", ""); r.Code != http.StatusNotFound {
		t.Fatalf("cross-account invoice: %d", r.Code)
	}
}
