	if got, want := r.Body.String(), "id,name,email,plan,created_at\r\n"; got != want {
		t.Fatalf("body %q, want %q", got, want)
	}
}

func TestCustomersCSVQuotesFieldsAsRFC4180(t *testing.T) {
	srv, st := newServer(t)
	now := time.Date(2026, 1, 2, 3, 4, 5, 0, time.UTC)
	name := "Doe, \"Jane\"\nJr"
	c, _ := st.CreateCustomer("acc_acme", name, `jane"@example.com`, store.PlanFree, now)

	body := do(t, srv, "GET", "/api/customers.csv", "key-acme", "").Body.String()
	if strings.ReplaceAll(body, "\r\n", "") != strings.ReplaceAll(body, "\r\n", "") || strings.Count(strings.ReplaceAll(body, "\r\n", ""), "\n") != 0 {
		t.Fatalf("a bare LF line ending in %q", body)
	}
	if !strings.HasSuffix(body, "\r\n") {
		t.Fatalf("the body does not end with CRLF: %q", body)
	}
	rows := parseCSV(t, body)
	if len(rows) != 2 || len(rows[1]) != 5 {
		t.Fatalf("rows %q", rows)
	}
	if rows[1][0] != c.ID || rows[1][1] != name || rows[1][2] != `jane"@example.com` {
		t.Fatalf("the quoted fields did not survive: %q", rows[1])
	}
}

func TestCustomersCSVGuardsAgainstFormulaInjection(t *testing.T) {
	srv, st := newServer(t)
	now := time.Date(2026, 1, 2, 3, 4, 5, 0, time.UTC)
	cases := []struct{ name, email, wantName, wantEmail string }{
		{`=HYPERLINK("http://evil.test","x")`, "=evil@example.com", `'=HYPERLINK("http://evil.test","x")`, "'=evil@example.com"},
		{"+1+1", "+plus@example.com", "'+1+1", "'+plus@example.com"},
		{"-2+3", "-minus@example.com", "'-2+3", "'-minus@example.com"},
		{"@SUM(A1)", "at@example.com", "'@SUM(A1)", "at@example.com"},
		{"Plain = Name", "a=b@example.com", "Plain = Name", "a=b@example.com"},
	}
	ids := map[string]string{}
	for _, tc := range cases {
		c, err := st.CreateCustomer("acc_acme", tc.name, tc.email, store.PlanFree, now)
		if err != nil {
			t.Fatal(err)
		}
		ids[c.ID] = tc.name
	}

	rows := parseCSV(t, do(t, srv, "GET", "/api/customers.csv", "key-acme", "").Body.String())
	if len(rows) != len(cases)+1 {
		t.Fatalf("got %d rows", len(rows))
	}
	for i, tc := range cases {
		row := rows[i+1]
		if row[1] != tc.wantName || row[2] != tc.wantEmail {
			t.Fatalf("row %q: name %q email %q, want %q and %q", row, row[1], row[2], tc.wantName, tc.wantEmail)
		}
	}
}

func TestCustomersCSVNeverListsAnotherAccountsCustomers(t *testing.T) {
	srv, st := newServer(t)
	c, _ := st.CreateCustomer("acc_globex", "Hank", "hank@globex.test", store.PlanFree, time.Now())
	rows := parseCSV(t, do(t, srv, "GET", "/api/customers.csv", "key-acme", "").Body.String())
	if len(rows) != 1 {
		t.Fatalf("another account's customer is exported: %q", rows)
	}
	if strings.Contains(do(t, srv, "GET", "/api/customers.csv", "key-acme", "").Body.String(), c.ID) {
		t.Fatalf("another account's customer ID is exported")
	}
}

